contract InvMutTest {
    C c;
    IERC20 clp;

    constructor(C _c) {
        c = _c;
        clp = c.clpToken();
    }

    // single public entrypoint with parameters: caller address (as bytes32 to then call via low-level), amount
    // We cannot change msg.sender for calls from this contract, so we simulate operator vs non-operator by
    // using c.setOperator from owner in setup: the deploying test contract is the owner of c (per C constructor),
    // so we can set operator to either this contract or to some other address (an arbitrary non-contract address).
    function run(address maybeOperator, uint256 amount) public payable {
        require(address(this) != address(0)); // trivial guard to satisfy template; does not restrict behavior

        // Set operator to maybeOperator (onlyOwner callable since this test contract deployed C)
        c.setOperator(maybeOperator);

        // Record CLP token balance of c before
        uint256 before = clp.balanceOf(address(c));

        // Try calling depositAndStake from THIS contract (msg.sender == address(this)).
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after
        uint256 after = clp.balanceOf(address(c));

        // If this contract is the configured operator, call must NOT revert. If it is not operator, call must revert.
        // Additionally, if the call reverted, the CLP balance of c must be unchanged; if it did not revert, balance may be >= before.
        bool amOperator = (maybeOperator == address(this));

        assert((amOperator && !reverted) || (!amOperator && reverted && after == before));
    }

    receive() external payable {}
}

