contract InvMutTest {
    C c;
    IERC20 clp;

    constructor(C _c) {
        c = _c;
        clp = c.clpToken();
    }

    // single public entrypoint
    function run(address maybeOperator, uint256 amount, address to) public payable {
        require(address(this) != address(0));

        // Set operator to maybeOperator (caller is this contract which the harness makes the owner)
        c.setOperator(maybeOperator);

        // read CLP balance of c before
        uint256 beforeBalance = clp.balanceOf(address(c));

        // try calling withdrawAndUnwrap(amount, claim=false, to) as this contract
        bool reverted;
        try c.withdrawAndUnwrap(amount, false, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read CLP balance of c after
        uint256 afterBalance = clp.balanceOf(address(c));

        // compute whether this contract is operator or owner
        bool isOperator = (maybeOperator == address(this));
        bool isOwner = (c.owner() == address(this));

        // Assert the general rule:
        // If caller is neither operator nor owner, the call must revert and leave CLP balance unchanged.
        // If caller is operator or owner, the call is allowed to succeed (may or may not change balance).
        assert((!isOperator && !isOwner && reverted && afterBalance == beforeBalance) || ((isOperator || isOwner) && !reverted));
    }

    receive() external payable {}
}

