contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to withdraw, claim flag, recipient address, callerSelector (0=operator,1=owner,2=other)
    function run(uint256 amount, bool claim, address to, uint8 callerSelector) public payable {
        require(callerSelector <= 2);

        // read balances before
        uint256 beforeClp = c.clpToken().balanceOf(address(c));

        // determine caller: we can only call as this contract. Use operator/owner by making c's operator or owner equal to this contract
        // We cannot change owner/operator because onlyOwner functions exist, but constructor of c set operator and owner already. However the test environment deploys a fresh c; we can't assume owner/operator values.
        // To respect constraints, we call withdrawAndUnwrap and catch whether it reverts; we then observe post-state.

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterClp = c.clpToken().balanceOf(address(c));

        // If call succeeded (not reverted), the contract's CLP balance must not have increased.
        // Also if call succeeded and 'to' is non-zero, the amount transferred out cannot exceed the requested amount: so afterClp >= beforeClp - amount.
        // We avoid underflow by writing inequality differently.

        if (!reverted) {
            // afterClp <= beforeClp
            // and if amount <= beforeClp, then afterClp >= beforeClp - amount  (i.e., at most 'amount' sent out)
            // If amount > beforeClp some unstake may have occurred, but still overall CLP balance shouldn't increase.
            assert(afterClp <= beforeClp && (amount > beforeClp || afterClp + amount >= beforeClp));
        } else {
            // If reverted, no strong state guarantees; still assert that CLP balance is unchanged when reverted
            assert(afterClp == beforeClp);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to withdraw, claim flag, recipient address
    function run(uint256 amount, bool claim, address to) public payable {
        // observe before balance
        uint256 beforeClp = c.clpToken().balanceOf(address(c));

        bool reverted;
        // call must be a top-level statement
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterClp = c.clpToken().balanceOf(address(c));

        // Single assert expressing the general rule:
        // If reverted -> balance unchanged. If not reverted -> balance did not increase.
        // Additionally, if call succeeded and no unstake was required (amount <= beforeClp), then at most `amount` could have been sent out: afterClp >= beforeClp - amount.
        assert(
            (reverted && afterClp == beforeClp) ||
            (!reverted && afterClp <= beforeClp && (amount > beforeClp || afterClp + amount >= beforeClp))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: claimExtras flag
    function run(bool claimExtras) public payable {
        // Observe the set of reward tokens and their balances before the call via public getters
        // rewardTokens is public array, so we can read its length and individual elements
        uint256 len = c.rewardTokens().length;
        // cap len to avoid gas/very large arrays in prover environment; but we must not require on c state
        // we will just iterate up to len

        // sum balances before
