contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that withdrawAndUnwrap will not transfer out more CLP tokens than `amount` when `to` is non-zero,
    // and that if `to` is address(0) no transfer happens; observable rule:
    // After calling withdrawAndUnwrap(amount, claim, to), the CLP token balance of c plus the amount
    // transferred to `to` equals previous CLP balance plus any CLP that was withdrawn from staking (unstakeFromPool) up to `amount`.
    // Because we cannot observe internal unstake amount directly, we assert a safer invariant:
    // The sum of (c's clpToken balance after) and (if to!=0 then IERC20(clp).balanceOf(to) else 0) is >=
    // the sum of (c's clpToken balance before) and min(amount, previous stakedBalance + previous clp balance) - this ensures no token loss beyond what was requested.

    function run(uint256 amount, bool claim, address to) public payable {
        require(to != address(this), "to must not be test contract");
        // Read observable before-values
        IERC20 clp = c.clpToken();
        uint256 beforeCBalance = clp.balanceOf(address(c));
        uint256 beforeToBalance = (to == address(0)) ? 0 : clp.balanceOf(to);
        uint256 beforeStaked = c.stakedBalance();

        // Call the function and catch revert
        bool reverted = false;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCBalance = clp.balanceOf(address(c));
        uint256 afterToBalance = (to == address(0)) ? 0 : clp.balanceOf(to);

        // The general rule we assert:
        // If the call reverted, nothing observable must have changed (balances unchanged).
        // If it succeeded, the total CLP between c and `to` cannot be less than it was before minus 0 (no unexpected burn): so >= beforeCBalance + beforeToBalance.
        // Also, when to==address(0) the c balance should not have decreased by more than amount (it transfers `amount` to to when to!=0, otherwise no transfer expected).

        if (reverted) {
            assert(afterCBalance == beforeCBalance && afterToBalance == beforeToBalance);
        } else {
            // total balance non-decreasing (no burn on successful call)
            assert(afterCBalance + afterToBalance >= beforeCBalance + beforeToBalance);
            if (to == address(0)) {
                // if not sending out, c's balance should not drop below previous balance
                assert(afterCBalance >= beforeCBalance);
            } else {
                // if sending to `to`, c's balance decrease cannot exceed `amount`
                // i.e., beforeCBalance - afterCBalance <= amount  => afterCBalance >= beforeCBalance - amount
                // avoid underflow: use comparison rearranged
                if (beforeCBalance > amount) {
                    assert(afterCBalance >= beforeCBalance - amount);
                } else {
                    // when amount >= beforeCBalance, afterCBalance is allowed to be zero
                    assert(afterCBalance <= beforeCBalance);
                }
            }
        }
    }

    receive() external payable {}
}

