            reverted = true;
        }

        // read post-state (only allowed public observations)
        uint256 afterClp = c.clpToken().balanceOf(address(c));
        uint256 afterStaked = c.stakedBalance();

        // If call reverted, we can't say much about state changes inside c (must be no assumption about changes),
        // so assert a property that still holds whether or not it reverted.
        // General rule:
        //  - If not reverted and amount <= beforeClp then staked balance must be unchanged (no unstake happened).
        //  - If not reverted and amount > beforeClp then the decrease in staked balance (if any) is at most amount - beforeClp.

        if (!reverted) {
            if (amount <= beforeClp) {
                assert(afterStaked == beforeStaked);
            } else {
                // afterStaked >= beforeStaked - (amount - beforeClp)
                // rearranged to avoid underflow in assert expression: afterStaked + (amount - beforeClp) >= beforeStaked
                assert(afterStaked + (amount - beforeClp) >= beforeStaked);
            }
        } else {
            // if reverted, at minimum the clp token balance of the contract should not have increased beyond beforeClp + amount
            // (withdrawAndUnwrap either transfers out or reverts; it should not magically create CLP tokens).
            // Expressed as: afterClp <= beforeClp || afterClp <= beforeClp + amount (both imply no unnatural increase)
            // Use a single general condition: afterClp <= beforeClp + amount
            assert(afterClp <= beforeClp + amount);
        }
    }

    receive() external payable {}
}

