        address owner = c.owner();

        // perform the call as either operator, owner, or external non-privileged account
        bool reverted;
        // We cannot actually change msg.sender to `caller` inside this contract; instead we simulate
        // by using only allowed callers: this contract is the caller. To force both branches, we
        // check if this contract equals operator/owner and otherwise expect a revert.
        // The required general rule will relate revert flag to whether this contract is operator/owner.

        // Make the call and capture revert
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-state
        uint256 afterClp = c.clpToken().balanceOf(address(c));
        uint256 transferredTo = 0;
        if (to != address(0)) {
            // how much did `to` receive? We can read token balance of `to`.
            transferredTo = c.clpToken().balanceOf(to);
        }

        // General rule asserted:
        // 1) If the call succeeded (not reverted) then either the contract's clp balance did not underflow
        //    (i.e., afterClp <= beforeClp + amount) and at most `amount` was transferred to `to`.
        // 2) If the call reverted then this contract is neither operator nor owner.
        // We combine into single assert using observable values and revert flag.

        assert(
            (
                !reverted && afterClp + uint256(0) <= beforeClp + amount && (to == address(0) || transferredTo <= amount)
            ) || (
                reverted && (address(this) != op && address(this) != owner)
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry point
    function run(bool claimExtras) public payable {
        // Read observables before the call
        address[] memory rewards = c.rewardTokens();
        uint256 len = rewards.length;
        // capture balances of each reward token for contract c and for the rewardsRecipient (may be zero address)
        uint256[] memory beforeC = new uint256[](len);
        uint256[] memory beforeRecipient = new uint256[](len);
        address recipient = c.rewardsRecipient();
        for (uint i = 0; i < len; ++i) {
            beforeC[i] = IERC20(rewards[i]).balanceOf(address(c));
            if (recipient != address(0)) {
                beforeRecipient[i] = IERC20(rewards[i]).balanceOf(recipient);
            } else {
                beforeRecipient[i] = 0;
            }
        }

        // Perform the state-changing call as a top-level statement and capture whether it reverted
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after the call
        uint256[] memory afterC = new uint256[](len);
        uint256[] memory afterRecipient = new uint256[](len);
        for (uint i = 0; i < len; ++i) {
            afterC[i] = IERC20(rewards[i]).balanceOf(address(c));
            if (recipient != address(0)) {
                afterRecipient[i] = IERC20(rewards[i]).balanceOf(recipient);
            } else {
                afterRecipient[i] = 0;
            }
        }

        // General rule asserted as a single condition:
        // If the call reverted, nothing else is required by this test (revert is allowed).
        // If the call succeeded, then for each reward token either the contract's balance did not increase
        // (tokens may have been forwarded to rewardsRecipient) and the recipient's balance increased by at most
        // the difference of contract's before+earned (we can only observe balances), equivalently:
        // afterC[i] <= beforeC[i] + (afterRecipient[i] - beforeRecipient[i]) + 0
        // and recipient's increase is non-negative. We express a sound observable invariant:
        // for all i: afterC[i] + beforeRecipient[i] >= beforeC[i] + afterRecipient[i]

        assert(
            reverted || (len == 0) || (
                // when succeeded and there are tokens, the combined inequality must hold for all tokens
                (function() internal view returns (bool) {
                    for (uint j = 0; j < len; ++j) {
                        // avoid underflow by using >= comparisons only
                        if (!(afterC[j] + beforeRecipient[j] >= beforeC[j] + afterRecipient[j])) {
                            return false;
                        }
                    }
                    return true;
                })()
            )
        );
    }

    // Minimal IERC20 typed inside this test to call balanceOf; this is allowed since interfaces already exist in the compilation unit,
    // but redeclaring a small interface inside the test contract scope is permissible in Solidity. If not allowed, the global IERC20 is used.
    // However, to abide by the constraints (do not redeclare), we reference the existing IERC20 by name above.

    receive() external payable {}
}

