contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that withdrawAndUnwrap either reverts for unauthorized callers,
    // or if it succeeds and transfers out `amount` to a non-zero `to`, then
    // the observable CLP token balance of c decreases by at most `amount` (i.e.,
    // final_balance >= before_balance - amount).
    // We cannot access the internal token directly, but c exposes clpToken() getter
    // and clpToken is an IERC20; we will use its public balanceOf through the C's
    // clpToken getter and then call IERC20(balance token).balanceOf(address(c)).

    // Note: We must only read c through its public surface. We'll fetch clpToken
    // address via c.clpToken() and then call IERC20(token).balanceOf(address(c)).

    function run(address caller, uint256 amount, bool claim, address to) public payable {
        require(true);

        // Read before balance
        IERC20 token = IERC20(c.clpToken());
        uint256 before = token.balanceOf(address(c));

        // Attempt call as this contract (which is the deployer/owner of c per problem statement)
        // The test environment runs run() with msg.sender = InvMutTest; ownership status of this
        // contract relative to c is given by the harness (fresh c deployed with this contract as deployer).
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = token.balanceOf(address(c));

        // If the call reverted, then it must be because caller wasn't operator or owner.
        // We check that either it reverted, or the balance did not drop by more than `amount`.
        // Express: reverted || after >= before - amount
        // Avoid underflow in before - amount by rearranging: after + amount >= before
        assert(reverted || (after + amount >= before));
    }

    receive() external payable {}
}

