contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(uint256 amount) public payable {
        require(true);

        // observe pre-state: clp token balance held by C and whether CVX pool is shutdown
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));
        bool shutdown = c.isCvxShutdown();

        // perform the operation under test as caller; we must be operator to avoid revert from onlyOperator
        // setOperator is onlyOwner; InvMutTest is the deployer of c and hence owner, so call setOperator to set this contract as operator
        c.setOperator(address(this));

        // attempt depositAndStake; capture whether it reverted
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-state balance
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // General rule asserted:
        // - If the pool is shutdown, depositAndStake must be a no-op (cannot decrease or increase balance) and thus after == before and it must not revert.
        // - If not shutdown and call did not revert, then the contract's clpToken balance cannot have increased by more than amount (i.e., after >= before - amount) and it cannot be greater than before (deposit moves tokens out or leaves unchanged). We avoid underflow in expressions by rearranging.

        assert(
            (shutdown && !reverted && afterBalance == beforeBalance)
            || (
                !shutdown && !reverted && (
                    // afterBalance <= beforeBalance  AND  beforeBalance - afterBalance <= amount
                    (afterBalance <= beforeBalance) && ((beforeBalance - afterBalance) <= amount)
                )
            )
        );
    }

    // receive to allow token transfers if needed (not used here but permitted)
    receive() external payable {}
}

