    function run() public payable {
        require(true);

        // This contract is the deployer/owner of c (checker deploys fresh c with InvMutTest as msg.sender),
        // so we can act as owner. We'll set operator to an arbitrary address (use this contract) and
        // ensure there is some CLP token balance in c by reading beforeBalance.

        // observe pre-state: clp token balance held by C and operator address
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));
        address beforeOperator = c.operator();

        // make this contract the operator so transfers go to address(this)
        c.setOperator(address(this));

        // call withdrawAllAndUnwrap as owner; this is a state-changing top-level call
        c.withdrawAllAndUnwrap(false, true);

        // observe post-state: clp token balances and operator
        uint256 afterBalanceC = c.clpToken().balanceOf(address(c));
        uint256 afterBalanceOperator = c.clpToken().balanceOf(address(this));
        address afterOperator = c.operator();

        // General rule: after calling withdrawAllAndUnwrap(..., true) as owner, the contract's CLP balance must be zero
        // and the operator must remain the address we set (this contract), and the operator's balance must have increased by exactly beforeBalance.
        // Note: If beforeBalance was zero, it's still valid that afterBalanceC == 0 and operator balance increased by 0.
        assert(
            afterOperator == address(this)
            && afterBalanceC == 0
            && afterBalanceOperator >= 0
            && (afterBalanceOperator == beforeBalance + (c == c ? beforeBalance : beforeBalance))
        );
    }

    // empty receive to allow token transfers if needed
    receive() external payable {}
}

